function parseClaudeJson(text) {
  const raw = String(text || '').trim();
  const fenced = raw.match(/\x60\x60\x60(?:json)?\s*([\s\S]*?)\x60\x60\x60/);
  const candidate = fenced ? fenced[1] : raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
  try {
    return JSON.parse(candidate);
  } catch (e) {
    throw new Error('Claude did not return valid JSON. Raw reply: ' + raw.slice(0, 500));
  }
}
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const notes = parseClaudeJson($input.first().json.text);
const form = $('Paste a Meeting Transcript').first().json;
const biz = $('Config: Your Business').first().json;
const settings = $('Config: Agent Settings').first().json;

const list = (items) => (items && items.length)
  ? '<ul>' + items.map((i) => '<li>' + esc(i) + '</li>').join('') + '</ul>'
  : '<p><i>None</i></p>';
const actions = (notes.action_items || []).length
  ? '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Task</th><th>Owner</th><th>Due</th></tr>' +
    notes.action_items.map((a) => '<tr><td>' + esc(a.task) + '</td><td>' + esc(a.owner) + '</td><td>' + esc(a.due) + '</td></tr>').join('') +
    '</table>'
  : '<p><i>No action items found</i></p>';

let html = '<h2>' + esc(form['Meeting title']) + '</h2>' +
  '<h3>Summary</h3>' + list(notes.summary) +
  '<h3>Decisions</h3>' + list(notes.decisions) +
  '<h3>Action items</h3>' + actions;
if (settings.include_open_questions) html += '<h3>Open questions</h3>' + list(notes.open_questions);
html += '<p>The follow-up email is saved in your Gmail drafts. Review it before sending.</p>';

const attendees = String(form['Attendee emails'] || '').split(',').map((s) => s.trim()).filter(Boolean).join(', ');

return [{
  json: {
    notes_subject: 'Meeting notes: ' + form['Meeting title'],
    notes_html: html,
    follow_up_to: attendees || biz.your_email,
    follow_up_subject: notes.follow_up_email?.subject || ('Follow-up: ' + form['Meeting title']),
    follow_up_body: notes.follow_up_email?.body || '',
  },
}];
